#[derive(Parser, Debug)]
#[command(name = "hyperfine", version = "1.20.0", about = "A command-line benchmarking tool.", disable_help_flag = true, disable_version_flag = true, override_usage = "executable [OPTIONS] <command>...")]
struct Cli {
