                let std_val = stats.stddev.unwrap_or(0.0) * match display_time_unit.as_str() {
                    "microsecond" => 1_000_000.0,
                    "millisecond" => 1000.0,
                    "second" => 1.0,
                    _ => 1.0,
                };
                let user_val = stats.user * match display_time_unit.as_str() {
                    "microsecond" => 1_000_000.0,
