                let mean_fmt = format!("{:.1}", mean_val);
                let std_fmt = format!("{:.1}", std_val);
                let user_fmt = format!("{:.1}", user_val);
                let sys_fmt = format!("{:.1}", sys_val);
                let min_fmt = format!("{:.1}", min_val);
                let max_fmt = format!("{:.1}", max_val);

                // For second unit, formatting with 3 decimals? Need to handle
                // We'll use different formatting based on unit
                // For second, use 3 decimals, for others 1 decimal
                // Actually earlier example: for second, "0.011 s" (3 decimals) for mean, and user/system "0.000 s"
