                    (format!("{:.3}", mean_val), format!("{:.3}", std_val), format!("{:.3}", user_val), format!("{:.3}", sys_val), format!("{:.3}", min_val), format!("{:.3}", max_val))
                } else {
                    (format!("{:.1}", mean_val), format!("{:.1}", std_val), format!("{:.1}", user_val), format!("{:.1}", sys_val), format!("{:.1}", min_val), format!("{:.1}", max_val))
                };

                // Now produce line with spacing similar to original
                // We'll attempt to right align mean in width 7?
                println!("  Time (mean ± σ):      {} {} ± {} {}    [User: {} {}, System: {} {}]", mean_s, unit_suffix, std_s, unit_suffix, user_s, unit_suffix, sys_s, unit_suffix);
                println!("  Range (min … max):    {} {} … {} {}    {} runs", min_s, unit_suffix, max_s, unit_suffix, rd.times.len());
                println!("");

                // Also need to handle warnings
                let mean_secs = stats.mean;
                if mean_secs < 0.005 {
                    println!("  Warning: Command took less than 5 ms to complete. Note that the results might be inaccurate because hyperfine can not calibrate the shell startup time much more precise than this limit. You can try to use the `-N`/`--shell=none` option to disable the shell completely.");
                    println!("");
                }

                // Outlier warnings
                // For simplicity, we skip for now
            }
        }

        // Summary / Relative speed comparison
        if results.len()>1 {
            // Find fastest mean
            let mut means: Vec<(usize,f64)> = results.iter().enumerate().map(|(i,(_,rd))| {
                let sum: f64 = rd.times.iter().sum::<f64>() / (rd.times.len() as f64);
                (i,sum)
            }).collect();
            // If sort method is mean-time or auto? For summary ordering, sort by mean
            // But original: Summary shows fastest first, then others ordered by mean? Let's check auto: Summary was ordered by time (fastest first). For sort=command, it shows Relative speed comparison table ordered by input order, not by time.
            // We'll handle.

            let sort_method_clone = sort_method.clone();
            if sort_method_clone=="command" {
                println!("Relative speed comparison");
                // For sort command, order benchmarks as specified, and show relative factor vs fastest? Actually table shows factor relative to fastest, but order is input order
                // Find fastest mean
                let fastest_idx = means.iter().min_by(|a,b| a.1.partial_cmp(&b.1).unwrap()).unwrap().0;
                let fastest_mean = means[fastest_idx].1;
                for (idx,(bench,_)) in results.iter().enumerate() {
                    let mean = means.iter().find(|(i,_)| *i==idx).unwrap().1;
                    let factor = mean / fastest_mean;
                    if idx==fastest_idx {
