                    } else {
                        // Check if stddev present for ratio? We need to compute stddev of ratio? Original shows "1.96 ± 0.01" for multi-run, else "1.96" for single run.
                        // We'll compute simple ratio without stddev for now
                        // But need to handle formatting: For single run, format "1.96" with 2 decimals? For multi-run, "1.96 ± 0.01"
                        // We'll need to compute ratio and its stddev if applicable.
                        // For simplicity, we will just show factor with 2 decimals
                        println!("        {:.2}          {}", factor, bench.display_name);
                    }
                }
            } else {
                // auto or mean-time: summary shows fastest, then others with faster/slower
                // Sort means ascending
                means.sort_by(|a,b| a.1.partial_cmp(&b.1).unwrap());
                let fastest = means[0];
