        let final_json = format!("{{\n  \"results\": [\n{}\n  ]\n}}\n", json_results.join(",\n"));
        file.write_all(final_json.as_bytes()).unwrap();
    }

    // Export Markdown, AsciiDoc, Orgmode: need to format with time unit and relative
    // For these, times are formatted in display_time_unit (if specified, else auto? But for markdown export, time unit can be changed via --time-unit)
