            } else {
                let prec = std::cmp::max(step_dec, min_sig);
                let fmt = if prec==0 {
                    format!("{:.0}", current)
                } else {
                    format!("{:.*}", prec, current)
                };
                values_str.push(fmt);
            }
            current += step_f;
            idx+=1;
            if idx>10000 { break; }
        }
        param_defs.push(ParamDef{ var, values: values_str });
