        }
    }

    validate_count("--prepare", &prepare, num_benchmarks_total);
    validate_count("--conclude", &conclude, num_benchmarks_total);
    validate_count("--output", &output, num_benchmarks_total);

    // command-name validation
    if !command_name.is_empty() {
        if param_defs.is_empty() {
            let n = base_commands.len();
            if command_name.len() > n {
                eprintln!("Error: Too many --command-name options: Expected {} at most", n);
                std::process::exit(1);
            }
        } else {
            let n = expanded_commands.len();
            let c = command_name.len();
            if c!=0 && c!=1 && c!=n {
                eprintln!("Error: '--command-name' has been specified {} times. It has to appear exactly once, or exactly {} times (number of benchmarks)", c, n);
                std::process::exit(1);
            }
        }
    }

    // output policy validation
    for out in &output {
        if out=="null" || out=="pipe" || out=="inherit" { continue; }
        if out.contains('/') { continue; }
        else {
            eprintln!("Error: Unknown output policy '{}'. Use './{}' to output to a file named '{}'.", out, out, out);
            std::process::exit(1);
        }
    }

    // input validation
    if let Some(ref inp) = input {
        if inp!="null" {
            let p = Path::new(inp);
            if !p.exists() {
                eprintln!("Error: The file '{}' specified as '--input' does not exist", inp);
                std::process::exit(1);
            }
        }
    }

    // Determine style
    let style_str = style.unwrap_or_else(|| "auto".to_string());
    let style = style_str.as_str();

    let sort_method = sort.unwrap_or_else(|| "auto".to_string());

    let time_unit_opt = time_unit.clone();

    // Shell handling
    let shell_default_path = "/bin/sh".to_string();
    let effective_shell: Option<Vec<String>> = if shell_opt_str=="none" {
        None
    } else if shell_opt_str=="default" {
        Some(vec![shell_default_path.clone()])
    } else {
        // split by shell-words? We'll implement simple split respecting quotes (basic)
        // For simplicity, use shell-words crate if available, else split whitespace
        // We will attempt manual parse that handles quotes
        fn split_shell(s: &str) -> Vec<String> {
            let mut res = Vec::new();
            let mut cur = String::new();
            let mut in_single = false;
            let mut in_double = false;
            let mut escape = false;
            for c in s.chars() {
                if escape {
                    cur.push(c);
                    escape = false;
                    continue;
                }
                if c=='\\' && !in_single {
                    escape = true;
                    continue;
                }
                if c=='\'' && !in_double {
                    in_single = !in_single;
                    continue;
                }
                if c=='"' && !in_single {
                    in_double = !in_double;
                    continue;
                }
                if c.is_whitespace() && !in_single && !in_double {
                    if !cur.is_empty() {
                        res.push(cur.clone());
                        cur.clear();
                    }
                } else {
                    cur.push(c);
                }
            }
            if !cur.is_empty() {
                res.push(cur);
            }
            res
        }
        let parts = split_shell(&shell_opt_str);
        if parts.is_empty() {
            Some(vec![shell_default_path.clone()])
        } else {
            Some(parts)
        }
    };

    // Shell calibration for overhead measurement
    let mut shell_overhead = Duration::from_secs_f64(0.0);
    if let Some(ref shell_parts) = effective_shell {
        let shell_exe = &shell_parts[0];
        let shell_args = &shell_parts[1..];
        let mut times = Vec::new();
        for _ in 0..10 {
            let start = Instant::now();
            let mut cmd = ProcCommand::new(shell_exe);
            for a in shell_args {
                cmd.arg(a);
            }
            cmd.arg("-c");
            cmd.arg("");
            cmd.stdout(Stdio::null());
            cmd.stderr(Stdio::null());
            cmd.stdin(Stdio::null());
            match cmd.status() {
                Ok(st) => {
                    if !st.success() {
                        eprintln!("Error: Could not measure shell execution time. Make sure you can run '{} -c \"\"'.", shell_opt_str);
                        std::process::exit(1);
                    }
                    times.push(start.elapsed());
                },
                Err(_) => {
                    eprintln!("Error: Could not measure shell execution time. Make sure you can run '{} -c \"\"'.", shell_opt_str);
                    std::process::exit(1);
                }
            }
        }
        let sum: Duration = times.iter().sum();
        shell_overhead = sum / (times.len() as u32);
    }

    // Helper: parse ignore failure
    #[derive(Clone)]
    enum IgnoreMode {
        All,
        Codes(HashSet<i32>),
    }
    let ignore_mode: Option<IgnoreMode> = if let Some(ref s) = ignore_failure {
        if s.is_empty() || s=="all-non-zero" {
            Some(IgnoreMode::All)
        } else {
            let mut set = HashSet::new();
            for part in s.split(',') {
                let p = part.trim();
                if p.is_empty() { continue; }
                if let Ok(code) = p.parse::<i32>() {
                    set.insert(code);
                }
            }
            Some(IgnoreMode::Codes(set))
        }
    } else {
        None
    };

    // Function to execute a command string and return timing info
    // Returns (real_duration, user, system, exit_code, memory_bytes)
    fn execute_command(
        command_str: &str,
        shell_opt: &Option<Vec<String>>,
        iteration: usize,
        input_opt: &Option<String>,
        output_opt: &str,
        show_output: bool,
        shell_overhead: Duration,
    ) -> Result<(Duration, Duration, Duration, i32, u64), String> {
        // For memory tracking, we need to get per-run rusage via wait4
        // We'll implement using libc::wait4 if shell, else also.
        // To simplify, we will spawn and then wait4.

        // Build command
        // For shell mode, command is shell -c <command_str>
        // For none, parse command_str into argv via shell-words like parsing

        fn split_cmd(s: &str) -> Vec<String> {
            // Basic shell-words parsing handling quotes and escapes
            let mut res = Vec::new();
            let mut cur = String::new();
            let mut in_single = false;
            let mut in_double = false;
            let mut escape = false;
            for c in s.chars() {
                if escape {
                    cur.push(c);
                    escape = false;
                    continue;
                }
                if c=='\\' && !in_single {
                    escape = true;
                    continue;
                }
                if c=='\'' && !in_double {
                    in_single = !in_single;
                    continue;
                }
                if c=='"' && !in_single {
                    in_double = !in_double;
                    continue;
                }
                if c.is_whitespace() && !in_single && !in_double {
                    if !cur.is_empty() {
                        res.push(cur.clone());
                        cur.clear();
                    }
                } else {
                    cur.push(c);
                }
            }
            if !cur.is_empty() {
                res.push(cur);
            }
            res
        }

        let start = Instant::now();

        // We'll use unsafe to get child pid and use wait4
        let mut proc = if let Some(shell_parts) = shell_opt {
            let shell_exe = &shell_parts[0];
            let shell_args = &shell_parts[1..];
            let mut cmd = ProcCommand::new(shell_exe);
            for a in shell_args {
                cmd.arg(a);
            }
            cmd.arg("-c");
            cmd.arg(command_str);
            cmd.env("HYPERFINE_ITERATION", iteration.to_string());
            match input_opt {
                None => { cmd.stdin(Stdio::null()); },
                Some(s) if s=="null" => { cmd.stdin(Stdio::null()); },
                Some(file) => {
                    match File::open(file) {
                        Ok(f) => { cmd.stdin(Stdio::from(f)); },
                        Err(_) => { cmd.stdin(Stdio::null()); },
                    }
                }
            }
            if show_output {
                cmd.stdout(Stdio::inherit());
                cmd.stderr(Stdio::inherit());
            } else {
                match output_opt {
                    "null" => { cmd.stdout(Stdio::null()); cmd.stderr(Stdio::null()); },
                    "pipe" => { cmd.stdout(Stdio::piped()); cmd.stderr(Stdio::piped()); },
                    "inherit" => { cmd.stdout(Stdio::inherit()); cmd.stderr(Stdio::inherit()); },
                    _ => {
                        let path = if output_opt.starts_with("./") { &output_opt[2..] } else { output_opt };
                        match OpenOptions::new().create(true).write(true).truncate(true).open(path) {
                            Ok(f) => {
                                let f2 = f.try_clone().unwrap();
                                cmd.stdout(Stdio::from(f));
                                cmd.stderr(Stdio::from(f2));
                            },
                            Err(_) => {
                                cmd.stdout(Stdio::null());
                                cmd.stderr(Stdio::null());
                            }
                        }
                    }
                }
            }
            cmd.spawn().map_err(|e| e.to_string())?
        } else {
            let parts = split_cmd(command_str);
            if parts.is_empty() {
                let mut cmd = ProcCommand::new("true");
                cmd.env("HYPERFINE_ITERATION", iteration.to_string());
                match input_opt {
                    None => { cmd.stdin(Stdio::null()); },
                    Some(s) if s=="null" => { cmd.stdin(Stdio::null()); },
                    Some(file) => {
                        match File::open(file) {
                            Ok(f) => { cmd.stdin(Stdio::from(f)); },
                            Err(_) => { cmd.stdin(Stdio::null()); },
                        }
                    }
                }
                if show_output {
                    cmd.stdout(Stdio::inherit());
                    cmd.stderr(Stdio::inherit());
                } else {
                    match output_opt {
                        "null" => { cmd.stdout(Stdio::null()); cmd.stderr(Stdio::null()); },
                        "pipe" => { cmd.stdout(Stdio::piped()); cmd.stderr(Stdio::piped()); },
                        "inherit" => { cmd.stdout(Stdio::inherit()); cmd.stderr(Stdio::inherit()); },
                        _ => {
                            let path = if output_opt.starts_with("./") { &output_opt[2..] } else { output_opt };
                            match OpenOptions::new().create(true).write(true).truncate(true).open(path) {
                                Ok(f) => {
                                    let f2 = f.try_clone().unwrap();
                                    cmd.stdout(Stdio::from(f));
                                    cmd.stderr(Stdio::from(f2));
                                },
                                Err(_) => {
                                    cmd.stdout(Stdio::null());
                                    cmd.stderr(Stdio::null());
                                }
                            }
                        }
                    }
                }
                cmd.spawn().map_err(|e| e.to_string())?
            } else {
                let exe = parts[0].clone();
                let args = parts[1..].to_vec();
                let mut cmd = ProcCommand::new(&exe);
                cmd.args(&args);
                cmd.env("HYPERFINE_ITERATION", iteration.to_string());
                match input_opt {
                    None => { cmd.stdin(Stdio::null()); },
                    Some(s) if s=="null" => { cmd.stdin(Stdio::null()); },
                    Some(file) => {
                        match File::open(file) {
                            Ok(f) => { cmd.stdin(Stdio::from(f)); },
                            Err(_) => { cmd.stdin(Stdio::null()); },
                        }
                    }
                }
                if show_output {
                    cmd.stdout(Stdio::inherit());
                    cmd.stderr(Stdio::inherit());
                } else {
                    match output_opt {
                        "null" => { cmd.stdout(Stdio::null()); cmd.stderr(Stdio::null()); },
                        "pipe" => { cmd.stdout(Stdio::piped()); cmd.stderr(Stdio::piped()); },
                        "inherit" => { cmd.stdout(Stdio::inherit()); cmd.stderr(Stdio::inherit()); },
                        _ => {
                            let path = if output_opt.starts_with("./") { &output_opt[2..] } else { output_opt };
                            match OpenOptions::new().create(true).write(true).truncate(true).open(path) {
                                Ok(f) => {
                                    let f2 = f.try_clone().unwrap();
                                    cmd.stdout(Stdio::from(f));
                                    cmd.stderr(Stdio::from(f2));
                                },
                                Err(_) => {
                                    cmd.stdout(Stdio::null());
                                    cmd.stderr(Stdio::null());
                                }
                            }
                        }
                    }
                }
                match cmd.spawn() {
                    Ok(p) => p,
                    Err(_) => {
                        // command not found => return exit 127 quickly
                        let elapsed = start.elapsed();
                        let adjusted = if elapsed > shell_overhead { elapsed - shell_overhead } else { Duration::from_secs_f64(0.0) };
                        return Ok((adjusted, Duration::from_secs_f64(0.0), Duration::from_secs_f64(0.0), 127, 0));
                    }
                }
            }
        };

        // Wait using libc::wait4 to get rusage
        let pid = proc.id() as i32;
        // Need to use wait4
        let mut status: i32 = 0;
        let mut rusage = unsafe { std::mem::zeroed::<libc::rusage>() };
        let res = unsafe { libc::wait4(pid, &mut status as *mut i32, 0, &mut rusage as *mut libc::rusage) };
        let real_elapsed = start.elapsed();

        if res < 0 {
            // fallback
            let _ = proc.wait();
            let adjusted = if real_elapsed > shell_overhead { real_elapsed - shell_overhead } else { Duration::from_secs_f64(0.0) };
            return Ok((adjusted, Duration::from_secs_f64(0.0), Duration::from_secs_f64(0.0), 127, 0));
        }

        let exit_code = if libc::WIFEXITED(status) {
            libc::WEXITSTATUS(status)
        } else if libc::WIFSIGNALED(status) {
            128 + libc::WTERMSIG(status)
        } else {
            127
        };

        let user = Duration::new(rusage.ru_utime.tv_sec as u64, (rusage.ru_utime.tv_usec as u32)*1000);
        let system = Duration::new(rusage.ru_stime.tv_sec as u64, (rusage.ru_stime.tv_usec as u32)*1000);
        let mem_bytes = (rusage.ru_maxrss as u64) * 1024; // Linux reports KB

        let adjusted_real = if shell_opt.is_some() {
            if real_elapsed > shell_overhead {
                real_elapsed - shell_overhead
            } else {
                Duration::from_secs_f64(0.0)
            }
        } else {
            real_elapsed
        };

        Ok((adjusted_real, user, system, exit_code, mem_bytes))
    }

    // Helper to run setup, prepare, cleanup etc as shell commands (always via default shell? Or same shell?)
    // In hyperfine, setup/prepare/conclude/cleanup are executed via same shell? The docs say they use same shell?
    // We'll assume same shell as benchmark (or default shell if none? But for none, what shell to use for prepare? Probably default shell? Let's check.
    // In earlier test with -N and --prepare? We didn't test prepare with -N. Let's assume prepare uses same effective shell if not none, else uses default shell? Actually for -N, prepare should still use shell? Need to check original behavior.
    // Simpler: prepare etc use default shell (/bin/sh) unless --shell=none? But original allows --shell to affect those?
    // We'll use effective_shell for those as well, except when shell is none, use default shell for prepare etc? Let's see hyperfine docs: --prepare executed before each timing run, but shell? Likely uses same shell setting.
    // We'll use effective_shell if Some, else default.

    fn run_aux_command(cmd_str: &str, shell_opt: &Option<Vec<String>>, iteration: Option<usize>) -> std::process::ExitStatus {
