    //   If original does NOT contain placeholder, display name = original + " (var = value, ...)" ? Original keeps placeholder? Actually for "echo hello" with param x=a, expanded is still "echo hello" (since no placeholder). But display name we observed was "echo hello (x = a)" . So default display = original + suffix.
    //   For multiple params, suffix includes all param values: " (x = a, y = 1)" etc.

    // For custom name with suffix: When custom name provided and original missing placeholder, display = custom + suffix.

    // Let's implement function to build suffix string from missing_vars and params.

    fn build_suffix(missing: &[String], params: &HashMap<String,String>) -> String {
        if missing.is_empty() {
            return "".to_string();
        }
        // Sort missing for stable order (already sorted)
        let mut parts = Vec::new();
        for var in missing {
            if let Some(val) = params.get(var) {
                parts.push(format!("{} = {}", var, val));
