    fn compute_stats(times: &[f64], user_times: &[f64], system_times: &[f64]) -> Stats {
        let n = times.len() as f64;
        let sum: f64 = times.iter().sum();
        let mean = sum / n;
        let stddev = if times.len()<=1 {
            None
        } else {
            let var: f64 = times.iter().map(|&x| (x-mean)*(x-mean)).sum::<f64>() / (n - 1.0);
            Some(var.sqrt())
        };
        let mut sorted = times.to_vec();
        sorted.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let median = if sorted.len()%2==1 {
            sorted[sorted.len()/2]
        } else {
            (sorted[sorted.len()/2 -1] + sorted[sorted.len()/2])/2.0
        };
        let user_sum: f64 = user_times.iter().sum();
        let user_mean = user_sum / n;
        let sys_sum: f64 = system_times.iter().sum();
        let sys_mean = sys_sum / n;
        let min = sorted[0];
        let max = sorted[sorted.len()-1];
        Stats{ mean, stddev, median, user: user_mean, system: sys_mean, min, max }
    }

